 SELECT coalesce(min((occurred_at at time zone 'Asia/Bangkok')::date),today),coalesce(max((occurred_at at time zone 'Asia/Bangkok')::date),today)
 INTO period_from,period_to FROM public.finance_cash_transactions WHERE status='confirmed';
 -- Execute through the granted authenticated role, including Invoice view RLS.
