 results:=ARRAY[public.get_finance_cash_flow_summary(period_from,period_to),public.get_finance_receivables_summary(),public.get_finance_general_payables_summary(),public.get_finance_unpaid_participants_summary()];
 -- Repeated reads must be stable within this statement and create no revisions.
