 -- Reference Invoice evidence is read through the same existing INVOKER view.
 SELECT coalesce(jsonb_agg(to_jsonb(r) order by currency),'[]') INTO expected_receivables FROM (
  select currency,count(*) outstanding_count,sum(outstanding_amount) outstanding_amount,
   count(*) filter(where is_overdue) overdue_count,coalesce(sum(outstanding_amount) filter(where is_overdue),0) overdue_amount,
   count(*) filter(where due_date between today and today+30) due_soon_count,coalesce(sum(outstanding_amount) filter(where due_date between today and today+30),0) due_soon_amount,
   count(*) filter(where due_date is null) no_due_date_count,coalesce(sum(outstanding_amount) filter(where due_date is null),0) no_due_date_amount
  from public.finance_invoice_settlement_summary where invoice_status='issued' and outstanding_amount>0 group by currency
 ) r;
 EXECUTE format('SET LOCAL ROLE %I',original_role);
 result:=results[1];
 IF jsonb_typeof(result) IS DISTINCT FROM 'object' OR
  (select array_agg(k order by k) from jsonb_object_keys(result) k) IS DISTINCT FROM ARRAY['as_of','currencies','from_date','schema_version','scope','semantics','timezone','to_date']::text[] OR
  result->'schema_version' IS DISTINCT FROM '1'::jsonb OR result->>'semantics' IS DISTINCT FROM 'period' OR
