  (result->>'as_of')::timestamptz IS DISTINCT FROM statement_timestamp() OR result->>'scope' IS DISTINCT FROM 'visible_accounts' OR (result->>'from_date')::date IS DISTINCT FROM period_from OR (result->>'to_date')::date IS DISTINCT FROM period_to
 THEN RAISE EXCEPTION '071_RPC_1_RESULT_SHAPE'; END IF;
 IF (select count(*)<>count(distinct v->>'currency') from jsonb_array_elements(result->'currencies') v)
 THEN RAISE EXCEPTION '071_RPC_1_DUPLICATE_CURRENCY'; END IF;
 FOR entry IN select value from jsonb_array_elements(result->'currencies') LOOP
  IF (select array_agg(k order by k) from jsonb_object_keys(entry) k) IS DISTINCT FROM ARRAY['currency','external_inflow','external_inflow_count','external_outflow','external_outflow_count','internal_transfer_amount','internal_transfer_count']::text[] OR
   jsonb_typeof(entry->'currency') IS DISTINCT FROM 'string' OR coalesce(length(entry->>'currency'),0)=0
  THEN RAISE EXCEPTION '071_RPC_1_CURRENCY_SHAPE'; END IF;
  FOREACH metric IN ARRAY ARRAY['external_inflow_count','external_inflow','external_outflow_count','external_outflow','internal_transfer_count','internal_transfer_amount']::text[] LOOP
   IF jsonb_typeof(entry->metric) IS DISTINCT FROM 'number' OR (entry->>metric)::numeric<0 OR
    (metric like '%count' AND (entry->>metric)::numeric<>trunc((entry->>metric)::numeric))
   THEN RAISE EXCEPTION '071_RPC_1_INVALID_METRIC: %',metric; END IF;
  END LOOP;
 END LOOP;
 result:=results[2];
 IF jsonb_typeof(result) IS DISTINCT FROM 'object' OR
  (select array_agg(k order by k) from jsonb_object_keys(result) k) IS DISTINCT FROM ARRAY['as_of','as_of_date','currencies','due_soon_from','due_soon_through','schema_version','semantics','timezone']::text[] OR
  result->'schema_version' IS DISTINCT FROM '1'::jsonb OR result->>'semantics' IS DISTINCT FROM 'current' OR
