  result->'schema_version' IS DISTINCT FROM '1'::jsonb OR result->>'semantics' IS DISTINCT FROM 'current' OR
  result->>'timezone' IS DISTINCT FROM 'Asia/Bangkok' OR jsonb_typeof(result->'currencies') IS DISTINCT FROM 'array' OR
  (result->>'as_of')::timestamptz IS DISTINCT FROM statement_timestamp() OR (result->>'as_of_date')::date IS DISTINCT FROM today OR (result->>'due_soon_from')::date IS DISTINCT FROM today OR (result->>'due_soon_through')::date IS DISTINCT FROM today+30
 THEN RAISE EXCEPTION '071_RPC_3_RESULT_SHAPE'; END IF;
 IF (select count(*)<>count(distinct v->>'currency') from jsonb_array_elements(result->'currencies') v)
 THEN RAISE EXCEPTION '071_RPC_3_DUPLICATE_CURRENCY'; END IF;
