  IF (select array_agg(k order by k) from jsonb_object_keys(entry) k) IS DISTINCT FROM ARRAY['company_purchase_amount','company_purchase_count','currency','due_soon_amount','due_soon_count','no_due_date_amount','no_due_date_count','outstanding_amount','outstanding_count','overdue_amount','overdue_count','reimbursement_amount','reimbursement_count']::text[] OR
