   jsonb_typeof(entry->'currency') IS DISTINCT FROM 'string' OR coalesce(length(entry->>'currency'),0)=0 OR jsonb_typeof(entry->'oldest_unpaid_at') IS DISTINCT FROM 'string'
  THEN RAISE EXCEPTION '071_RPC_4_CURRENCY_SHAPE'; END IF;
