 END LOOP;
 -- Independent source-row reconciliation: cash only (no opening, VAT/WHT additions),
 -- transfer IDs once rather than both linked cash legs, currencies never combined.
 WITH cash AS MATERIALIZED (
  select c.* from public.finance_cash_transactions c where c.status='confirmed'
   and c.occurred_at>=period_from::timestamp at time zone 'Asia/Bangkok' and c.occurred_at<(period_to+1)::timestamp at time zone 'Asia/Bangkok'
   and public.treasury_can_view(c.bank_account_id,c.cash_location_id)
 ), external_cash AS (
  select c.* from cash c where not exists(select 1 from public.finance_treasury_transfer_legs l where l.cash_transaction_id=c.id)
 ), transfer_amounts AS (
  select distinct c.currency,l.transfer_id,c.cash_amount from cash c join public.finance_treasury_transfer_legs l on l.cash_transaction_id=c.id
 ), currencies AS (select distinct currency from cash)
 SELECT coalesce(jsonb_agg(jsonb_build_object('currency',x.currency,
  'external_inflow_count',(select count(*) from external_cash e where e.currency=x.currency and direction='inflow'),
  'external_inflow',(select coalesce(sum(cash_amount),0) from external_cash e where e.currency=x.currency and direction='inflow'),
  'external_outflow_count',(select count(*) from external_cash e where e.currency=x.currency and direction='outflow'),
  'external_outflow',(select coalesce(sum(cash_amount),0) from external_cash e where e.currency=x.currency and direction='outflow'),
  'internal_transfer_count',(select count(*) from transfer_amounts t where t.currency=x.currency),
  'internal_transfer_amount',(select coalesce(sum(cash_amount),0) from transfer_amounts t where t.currency=x.currency)) order by x.currency),'[]') INTO expected_cash FROM currencies x;
 -- EXISTS predicates avoid multiplying balances through source/settlement joins.
 WITH unpaid AS (
  select o.* from public.finance_expense_obligations o
  where o.source_type in ('supplier_payable','employee_reimbursement')
   and exists(select 1 from public.finance_expenses e where e.id=o.expense_id and e.status='accepted')
   and not exists(select 1 from public.finance_expense_obligation_waivers w where w.obligation_id=o.id)
   and not exists(select 1 from public.finance_payout_allocations a where a.expense_obligation_id=o.id)
 ) SELECT coalesce(jsonb_agg(to_jsonb(r) order by currency),'[]') INTO expected_payables FROM (
  select currency,count(*) outstanding_count,sum(gross_amount) outstanding_amount,
   count(*) filter(where source_type='supplier_payable') company_purchase_count,coalesce(sum(gross_amount) filter(where source_type='supplier_payable'),0) company_purchase_amount,
   count(*) filter(where source_type='employee_reimbursement') reimbursement_count,coalesce(sum(gross_amount) filter(where source_type='employee_reimbursement'),0) reimbursement_amount,
   count(*) filter(where due_on<today) overdue_count,coalesce(sum(gross_amount) filter(where due_on<today),0) overdue_amount,
   count(*) filter(where due_on between today and today+30) due_soon_count,coalesce(sum(gross_amount) filter(where due_on between today and today+30),0) due_soon_amount,
   count(*) filter(where due_on is null) no_due_date_count,coalesce(sum(gross_amount) filter(where due_on is null),0) no_due_date_amount
  from unpaid group by currency
 ) r;
 WITH unpaid AS (
  select e.* from public.finance_payable_entitlements e where e.status='open' and e.recipient_type='user' and e.bucket in ('referral','work')
   and exists(select 1 from public.finance_payable_entitlement_sources s where s.distribution_id=e.distribution_id and s.status='open')
   and exists(select 1 from public.finance_vp_revenue_distributions d where d.id=e.distribution_id and d.status='finalized' and d.revision=e.distribution_revision and
    ((e.source_type='payment' and d.payment_id=e.received_money_id and exists(select 1 from public.finance_payments p where p.id=e.received_money_id and p.status='confirmed')) or
     (e.source_type='direct_money_receipt' and d.direct_money_receipt_id=e.received_money_id and exists(select 1 from public.finance_direct_money_receipts p where p.id=e.received_money_id and p.status='confirmed'))))
   and not exists(select 1 from public.finance_payout_allocations a where a.entitlement_id=e.id)
 ) SELECT coalesce(jsonb_agg(to_jsonb(r) order by currency),'[]') INTO expected_participants FROM (
  select currency,count(*) unpaid_entitlement_count,count(distinct recipient_id) unpaid_participant_count,sum(gross_amount) unpaid_amount,min(finalized_at) oldest_unpaid_at from unpaid group by currency
 ) r;
 IF results[1]->'currencies' IS DISTINCT FROM expected_cash THEN RAISE EXCEPTION '071_CASH_TRANSFER_ANTI_INFLATION'; END IF;
 IF results[2]->'currencies' IS DISTINCT FROM expected_receivables THEN RAISE EXCEPTION '071_RECEIVABLE_SETTLEMENT_TOTALS'; END IF;
 IF results[3]->'currencies' IS DISTINCT FROM expected_payables THEN RAISE EXCEPTION '071_GENERAL_PAYABLES_SEPARATION_OR_SETTLEMENT'; END IF;
 IF results[4]->'currencies' IS DISTINCT FROM expected_participants THEN RAISE EXCEPTION '071_PARTICIPANT_FULL_SETTLEMENT_OR_DUPLICATION'; END IF;
 -- All four RPCs have run twice. No business rows, definitions, grants or views may change.
 EXECUTE capture_sql INTO actual;
 select coalesce(jsonb_agg(jsonb_build_object('section',s,'object',k,'expected',expected->s->k,'actual',actual->s->k) order by s,k),'[]') from unnest(array['functions','catalog','views','rows']) s cross join lateral (select jsonb_object_keys(expected->s) k union select jsonb_object_keys(actual->s) k) keys where actual->s->k is distinct from expected->s->k INTO failures;
 IF failures IS DISTINCT FROM '[]'::jsonb THEN RAISE EXCEPTION '071_READ_SIDE_EFFECT: %',failures; END IF;
END;
$gate071$;
